INSERT INTO `kanji` VALUES (1,'Ichi/Itsu','Hito','Jeden','ichi.png','Prosta kreska przypomina liczbę 1.','一人 (ひとり - jedna osoba), 一つ (ひとつ - jedna rzecz)'),(2,'Ni','Futa','Dwa','ni.png','Dwie poziome kreski 1+1=2, 一 + 一 = 二.','二人 (ふたり - dwie osoby), 二つ (ふたつ - dwie rzeczy)'),(3,'San','Mitsu/Mi-','Trzy','san.png','Trzy poziome kreski 1+2=3, 一 + 二 = 三.','三人 (さんにん - trzy osoby), 三つ (みっつ - trzy rzeczy)'),(4,'Shi','Yo/Yu/Yon','Cztery','shi.png','Kwadrat ma 4 boki.','四人 (よにん - cztery osoby), 四つ (よっつ - cztery rzeczy)'),(5,'Go','Itsu','Pięć','go.png','Przypomina liczbę 5.','五人 (ごにん - pięć osób), 五つ (いつつ - pięć rzeczy)'),(6,'Roku','Mu/Mut/Mui','Sześć','roku.png','Kształt przypomina rzymską liczbę VI, gdzie V jest obrócone do dołu, a I poziomo.','六人 (ろくにん - sześć osób), 六つ (むっつ - sześć rzeczy)'),(7,'Shichi','Nana/Nano','Siedem','nana.png','Kształtem przypomina odwróconą cyfrę 7.','七人 (しちにん - siedem osób), 七つ (ななつ - siedem rzeczy)'),(8,'Hachi','Yat/Ya/You','Osiem','hachi.png','Linie biegną wzdłuż kształtu cyfry 8.','八人 (はちにん - osiem osób), 八つ (やっつ - osiem rzeczy)'),(9,'Kyuu/Ku','Kokono','Dziewięć','kyuu(nine).png','-','九人 (きゅうにん - dziewięć osób), 九つ (ここのつ - dziewięć rzeczy)'),(10,'Juu/Ji','Too','Dziesięć','juu.png','Po obróceniu znaku przypomina rzymską cyfrę 10, czyli X.','十人 (じゅうにん - dziesięć osób), 十つ (とお - dziesięć rzeczy)'),(11,'Hyaku',NULL,'Sto','hyaku.png','Przypomina obróconą liczbę 100.','百人 (ひゃくにん - sto osób), 百円 (ひゃくえん - sto jenów)'),(12,'Sen','Chi','Tysiąc','sen.png','Składa się z litery T jak tysiąc.','千人 (せんにん - tysiąc osób), 千円 (せんえん - tysiąc jenów)'),(13,'Man/Ban',NULL,'Dziesięć tysięcy','man.png','Połączone litery \"T\" i \"h\", skojarzyć można jak z angielskiego Ten thousand.','万人 (まんにん - dziesięć tysięcy osób), 万円 (まんえん - dziesięć tysięcy jenów)'),(14,'Sui','Mizu','Woda','sui.png','Znak przypomina ważkę latającą nad taflą [wody].','水曜日 (すいようび - środa), 水道 (すいどう - wodociąg)'),(15,'Ka','Hi','Ogień','hi.png','Znak ten przypomina kształt ogniska.','火事 (かじ - pożar), 火山 (かざん - wulkan)'),(16,'Boku/Moku','Ki/Ko','Drzewo,Drewno','boku-moku.png','Znak przypomina drzewo.','木曜日 (もくようび - czwartek), 木 (き - drzewo)'),(17,'Ten','Ame/Ama','Niebo','ten.png','Niebo jest jedną 一 dużą 大 przestrzenią nad nami.','天気 (てんき - pogoda), 天使 (てんし - anioł)'),(18,'Do/To','Tsuchi','Ziemia','do-to.png','Przypomina krzyż zakopany w ziemi.','土曜日 (どようび - sobota), 土地 (とち - ziemia, teren)'),(19,'Hoku','Kita','Północ','hoku.png','Obracając znak do środka przypomina drabinę którą można iść do góry.','北風 (きたかぜ - północny wiatr), 北海道 (ほっかいどう - Hokkaido)'),(20,'Tou','Higashi','Wschód','tou.png','Wschód to kierunek, z którego wschodzi słońce 日 za drzewem 木.','東風 (とうふう - wschodni wiatr), 東京 (とうきょう - Tokyo)'),(21,'Sei/Sai','Nishi','Zachód','sei-sai.png','Górna część znaku przypomina grecki znak Pi (π), a Grecja leży na zachodzie.','西洋 (せいよう - Zachód), 西風 (にしかぜ - zachodni wiatr)'),(22,'Nan','Minami','Południe','nan.png','Przypomina lotkę strzały skierowanej w dół.','南風 (みなみかぜ - południowy wiatr), 南極 (なんきょく - Antarktyda)'),(23,'Sa','Hidari','Lewo','sa.png','-','左手 (ひだりて - lewa ręka), 左右 (さゆう - lewo i prawo)'),(24,'U/Yuu','Migi','Prawo','u-yu.png','Kwadrat jest po prawej stronie skrzyżowania.','右手 (みぎて - prawa ręka), 右側 (みぎがわ - prawa strona)'),(25,'Nichi/Jitsu','Hi/Ka','Dzień,Słońce','nichi-jitsu.png','Przypomina ramę okna przez którą wpadają promienie słoneczne.','日曜日 (にちようび - niedziela), 日本 (にほん - Japonia)'),(26,'Getsu/Gatsu','Tsuki','Miesiąc,Księżyc','getsu-gatsu.png','Znak przypomina niewielką zagiętą część księżyca, potocznie w kształcie rogala.','月曜日 (げつようび - poniedziałek), 月 (つき - księżyc)'),(27,'Ka','Hana','Kwiat','ka.png','Górna część znaku przypomina trawę w ziemi, dolny znak 化 oznacza zmianę, trawa zmienia się w kwiaty.','花見 (はなみ - oglądanie kwiatów wiśni), 花火 (はなび - fajerwerki)'),(28,'Gyo','Sakana/Uo','Ryba','gyo.png','Przypomina ogon ryby.','魚屋 (さかなや - sklep rybny), 金魚 (きんぎょ - złota rybka)'),(29,'Kuu','Sora/A.../Kara','Niebo,Pusty,Pustka,Próżnia','kuu.png','-','空気 (くうき - powietrze), 空港 (くうこう - lotnisko)'),(30,'San','Yama','Góra','san(yama).png','Po połączeniu ze sobą pionowych linii znak przypomina górę','山登り (やまのぼり - wspinaczka górska), 富士山 (ふじさん - góra)'),(31,'Sen','Kawa','Rzeka','sen(kawa).png','Trzy pionowe linie przypominają prąd rzeczny.','川沿い (かわぞ - wzdłuż rzeki), 川辺 (かわべ - brzeg rzeki)'),(32,'U','Ame/Ama','Deszcz','u(ame).png','Przypomina krople deszczu uderzające w okno.','雨天 (うてん - deszczowa pogoda), 梅雨 (つゆ - pora deszczowa)'),(33,'Hon','Moto','Książka','hon.png','Książka zrobiona jest z drzewa które ścinane jest u podstawy.','本屋 (ほんや - księgarnia), 本当 (ほんとう - prawda)'),(34,'Moku','Me','Oko','moku.png','Po obruceniu do poziomu, przypomina oko i źrenicę.','目標 (もくひょう - cel, punkt), 目的 (もくてき - cel do którego się dąży)'),(35,'Kou/Ku','Kuchi','Usta','kou-ku.png','Znak przypomina szeroko otwartą buzię.','口座 (こうざ - konto bankowe), 火口 (かこう - wulkaniczny krater)'),(36,'Ji','Mimi','Ucho','ji.png','Znak przypomina ucho z otworem na środku i przedłużone u dołu.','耳鼻科 (じびか - laryngologia), 耳孔 (じこう - otwór w uchu)'),(37,'Shu','Te','Ręka','shu.png','Przypomina dłoń pokazującą kciuk w dół.','手紙 (てがみ - list), 空手 (からて - karate)'),(38,'Soku','Ashi/Ta...','Stopa','soku.png','Przypomina postać z dużymi stopami.','足音 (あしおと - dźwięk kroków), 満足 (まんぞく - zadowolenie)'),(39,'Jin/Nin','Hito','Osoba','jin-nin.png','Znak ten przypomina postać stojącą na nogach, symbolizującą człowieka.','人間 (にんげん - człowiek/istota ludzka), 人口 (じんこう - populacja)'),(40,'Bo','Haha','Matka','bo.png','Przypomina łono matki w którym rozwija się życie.','母親 (ははおや - matka), 祖母 (そぼ - babcia)'),(41,'Fu','Chichi','Ojciec','fu.png','Przypomina dach, ojciec daje dach nad głową.','父親 (ちちおや - ojciec), 祖父 (そふ - dziadek)'),(42,'Jo','Onna/Me','Kobieta','jo.png','Przypomina kłaniającą się balerine.','女性 (じょせい - kobieta), 女王 (じょおう - księżniczka)'),(43,'Dan/Nan','Otoko','Mężczyzna','dan-nan.png','Na górze pole ryżowe, na dole siła, To połączenie symbolizuje mężczyznę jako pracowitego, silnego i zdolnego do ciężkiej pracy.','男性 (だんせい - mężczyzna), 男優 (たんよう - aktor)'),(44,'Shi/Su','Ko','Dziecko','shi-su.png','Przypomina dziecko stojące na jednej nodze z rozłożonymi rękoma próbując utrzymać równowagę.','子供 (こども - dziecko), 小指 (こゆび - mały palec)'),(45,'Shou','Chiisai/Ko/O','Małe','shou.png','Dwie małe ryby pływają wokół haczyka.','小説 (しょうせつ - powieść), 小麦 (こむぎ - pszenica)'),(46,'Chuu','Naka','W środku','chuu.png','Pionowa linia przechodzi przez środek prostokąta.','中学校 (ちゅうがっこう - gimnazjum), 中国 (ちょうごく - Chiny)'),(47,'Dai/Tai','Ookii/Ooi','Duży,Dużo','dai-tai.png','Wygląda jak duży człowiek z szeroko rozłożonymi nogami i rękoma.','大人 (おとな - dorosły), 大学 (だいがく - szkoła wyższa)'),(48,'Jou/Shou','Ue/Kami/A(geru/garu)','Powyżej,Górny','jou-shou.png','Flaga zawieszona na górze masztu.','上司 (じょうし - przełożony), 上手 (じょうず - dobry/umiejętny)'),(49,'Ka/Ge','Shita/Sageru/Orosu/Kudaru','Poniżej,W dół','ka-ge.png','Wygląda jak sopel zwisający w dół z sufitu.','下手 (へた - niezdarny/nieumiejętny), 地下鉄 (ちかてつ - metro)'),(50,'Ka','Nani/Nan','Co,Ile,Które','ka(nani).png','Na górze znak dla czasu, a na dole dla miejsca, razem oznaczają pytanie o czas i miejsce.','何時 (なんじ - kiedy?/o której?), 何処 (どこ - gdzie?)'),(51,'Kou','Iku/Yuku/Okonau','Chodzić,Iść,Wykonać','kou(iku).png','Wygląda jak otwarty most zwodzony żeby statki mogły \"przejść\"/przepłynąć.','行く (いく - iść), 銀行 (ぎんこう - bank)'),(52,'Ken','Miru/Mieru/Miseru','Widzieć,Być widocznym,Pokazać','ken.png','Wygląda jak oko z nogami co może symbolizować \"czynność widzenia\".','見る (みる - widzieć), 見せる (みせる - pokazać)'),(53,'Gen/Gon','Iu','Mówić','gen.png','Słowa czyli linie wychodzące z ust 口.','言葉 (ことば - mowa/dialekt), 無言 (むごん - cisza)'),(54,'Go','Kata/Kataru','Słowo,Język','go(kata).png','Słowo 言 + 5 五 + usta 口 = 5 powiedzianych słów jest rozmową.','日本語 (にほんご - język japoński), 語彙 (ごい - słownictwo)'),(55,'Shoku','Taberu/Kuu/Kurau','Jedzenie,Jeść','shoku.png','Znak składa się ze czegoś dobrego 良 pod czymś przypominającym dach,a nie ma nic lepszego niż domowe jedzenie.','食べる (たべる - jeść), 食事 (しょくじ - posiłek)'),(56,'In','Nomu','Picie,Pić','in.png','Picie to jedzenie 食 ale brakuje 欠 czegoś solidnego.','飲食 (いんしょく - jedzenie i napoje), 飲み物 (のみもの - napój)'),(57,'Kai/E','Au','Spotkać,Społeczeństwo','kai.png','Znak przypomina osobę wyciągającą dłoń do uścisku, witamy się tak kiedy kogoś poznajemy.','会社 (かいしゃ - firma), 会話 (かいわ - rozmowa)'),(58,'Gaku','Manabu','Szkoła,Nauka,Uczyć się','gaku.png','Zawiera znak dziecka 子 pod czymś co przypomina dach. Szkoła to budnek w którym są dzieci.','学校 (がっこう - szkoła), 大学 (だいがく - szkoła wyższa)'),(59,'Kyuu','Yasumu','Odpoczywać','kyuu.png','Przypomina osobę stojącą obok drzewa 木, pod drzewem można odpoczywać.','休日 (きゅうじつ - dzień wolny), 休憩 (きゅうけい - przerwa)'),(60,'Bai','Kau','Kupić','bai.png','Przypomina regały sklepowe, na których są rzeczy, które można kupić.','買い戻す (かいもどす - odkupić), 買い物 (かいもの - zakupy)'),(61,'Bun/Mon','Kiku/Kikoeru','Słyszeć,Słuchać,Zapytać','bun-mon.png','Ktoś przykłada ucho 耳 do bramy, żeby słuchać 門.','聞こえる (きこえる - słyszeć), 新聞 (しんぶん - gazeta)'),(62,'Rai','Kuru/Kita','Przyjść','rai.png','Przypomina ogień 火 za płotem, nie wolno do niego [podchodzić].','来年 (らいねん - przyszły rok), 来訪 (らいほう - wizyta)'),(63,'Ritsu','Tatsu/Tateru','Stać,ustalić','ritsu.png','Przypomina zamek z kart, stoi, nie przewraca się.','立案 (りつあん - planowanie), 立場 (たちば - pozycja/sytuacja)'),(64,'Sei/Shou','Ikiru/Umu/Nama/Ki','Żyć,Rosnąć,Rodzić się,surowy','sei-shou.png','Wygląda jak roślina w ziemi, którą podlewamy żeby [rosła].','学生 (がくせい - student), 生まれる (うまれる - urodzić się)'),(65,'Wa','Hanashi/Hanasu','Mowa,Rozmawiać,Rozmowa','wa.png','Połączenie słowa 言 z językiem 舌 daje rozmowę.','会話 (かいわ - rozmowa), 話題 (わだい - temat rozmowy)'),(66,'Shutsu','Deru/Dasu','Wyjść','shutsu.png','Po połączeniu pionowych linii znak przypomina drzwi przez które można wyjść.','日の出 (ひので - wschód słońca), 出口 (でぐち - wyjście)'),(67,'Doku/Toku','Yomu','Czytać','doku-toku.png','Znak ten składa się z słowa 言 oraz sprzedaży 売. Książki sprzedawane są żeby je czytać.','読む (よむ - czytać), 読書 (どくしょ - czytanie książek)'),(68,'Nyuu','Hairu/Iru/Ireru','Wejść,Włożyć','nyuu.png','Przypomina namiot do którego można wejść.','入る (はいる - wchodzić), 入口 (いりぐち - wejście)'),(69,'Sho','Kaku','Pisać','sho.png','Można wyobrazić sobie, że górna część znaku przypomina rękojeść a dół włosie pędzla, którym się pisze.','文書 (ぶんしょ - zdanie), 書類 (しょるい - dokumenty)'),(70,'Go/Kou','Ato/Okureru/Nochi','Po,Za,Później','go-kou.png','-','午後 (ごご - popołudnie), 後で (あとで - później)'),(71,'Ko','Furui','Stare,Zużyty','ko.png','Przypomina nagrobek z krzyżem, czyli rzecz jest już niezdatna do użytku ze starości.','中古車 (ちゅうこしゃ - zużyty samochód), 古本 (ふるほん - stara książka)'),(72,'Kou','Takai/Takamaru/Takameru','Wysoki,Drogie,Wzrost','kou(takai).png','Wygląda jak duża japońska świątynia.','高速 (こうそく - duża prędkość), 高校 (こうこう - liceum)'),(73,'An','Yasui','Tanie,Pokój,Bezpieczeństwo','an.png','Zapewnienie kobiecie 女 dachu (górna część znaku), nie jest tanie ale przynosi spokój i bezpieczeństwo.','安全 (あんぜん - bezpieczeństwo), 安売り (やすうり - wyprzedaż)'),(74,'Ta','Ooi','Wiele','ta.png','Jeden wieczór 夕 jest fajny ale dwa 多 to już za dużo.','多分 (たぶん - prawdopodobnie), 多数 (たすう - duża liczba)'),(75,'Shin','Atarashii/Arata','Nowy','shin.png','-','新しい (あたらしい - nowy), 新聞 (しんぶん - gazeta)'),(76,'Shou','Sukoshi/Sukunai','Trochę/Kilka','shou(sukoshi).png','Coś małego 小 przecięte, przez co jest jeszcze mniejsze.','少女 (しょうじょ - dziewczynka), 少年 (しょうねん - chłopiec)'),(77,'Chou','Nagai','Długi,Lider','chou.png','Przypomina grzebień, który może czesać długie włosy.','社長 (しゃちょう - Szef(CEO), 長時間 (ちょうじかん - długi czas)'),(78,'Haku/Byaku','Shiroi/Shiro','Biały','haku-byaku.png','Biały przypomina znak słońca 日. Słońce emituje białe światło.','白人 (はくじん - biały człowiek), 白鳥 (はくちょう - łabędź)'),(79,'Fun/Bu','Wakeru/Wakaru/Wakakeru','Część,Minuta,Dzielić,Rozumieć','fun-bu.png','-','自分 (じぶん - ja), 理解 (りかい - zrozumienie)'),(80,'Ji','Toki','Czas,Godzina','ji(toki).png','Złożone ze słońca 日 i świątyni 寺. W świątyni mnisi obserwują słońce w celu określenia godziny.','時計 (とけい - zegarek), 時間 (じかん - czas)'),(81,'Kan/Ken','Aida','Czas,Okres czasu','kan-ken.png','Promienie słońca 日 przechodzące przez bramę 門, rzucające cień, dobrze pokazują upływ czasu.','週間 (しゅうかん - okres tygodnia), 間に合う (まにあう - być na czas/zdążyć)'),(82,'Shuu','Hito','Tydzień','shuu.png','Znak przypomina osobę, która zmierza do kościoła jako znak nowego tygodnia.','今週 (こんしゅう - ten tydzień), 週末 (しゅうまつ - weekend)'),(83,'Nen','Toshi','Rok','nen.png','Przypomina drzewo, które w połowie jest latem pełne liści, a po drugiej stronie nie ma liści zimą, co symbolizować może cykl roku.','今年 (ことし - ten rok), 年間 (ねんかん - roczny/rok czasu)'),(84,'Kon/Kin','Ima','Teraz','kon-kin.png','Dolna część znaku przypomina wskazówki zegara, które pokazują, jaka jest [teraz] godzina.','今朝 (けさ - dziś rano), 今日 (きょう - dzisiaj)'),(85,'Sen','Saki','Przed(daleko)','sen(saki).png','Znak przypomina stojącego na podium człowieka machającego flagą [przed] ludźmi.','先ず (あず - przedewszystkim), 先週 (せんしゅう - zeszły tydzień)'),(86,'Zen','Mae','Przed(blisko)','zen.png','Znak przypomina radio. \"Codziennie [przed] śniadaniem słucham radia.','名前 (なまえ - imię), 午前 (ごぜん - poranek)'),(87,'Go',NULL,'Południe','go(noon).png','Znak 10 十 ,który ma dwie dodatkowe kreski, co daje 12, jak 12:00 (południe).','午前 (ご - poranek), 午後 (ごご - po południu)'),(88,'Han','Nakaba','Pół,W połowie','han.png','Pionowa linia dzieli znak idealnie na pół.','半年 (はんとし - pół roku), 半分 (はんぶん - połowa)'),(89,'Ten','Mise','Sklep','ten(mise).png','Znak przypomina stragan na targu. Stoisko pod namiotem.','店員 (てんいん - sprzedawca/pracownik sklepu), 店長 (てんちょう - menadżer sklepu)'),(90,'Gai/Ge','Soto/Hoka','Poza,Inny,Zagraniczny,Obcy','gai-ge.png','Wygląda jak znaki katakany ta タ i to ト. Katakaną zapisuje się słowa zapożyczone z języków [obcych].','外国 (がいこく - zagranica), 外国人 (がいじん - obcokrajowiec)'),(91,'Den',NULL,'Elektryczność','den.png','Część znaku przypomina deszcz 雨. Gdy jest burza, widać na niebie [elektryczne] błyskawice.','電気 (でんき - elektryczność), 電車 (でんしゃ - pociąg)'),(92,'Dou','Michi','Ulica,Droga,Ścieżka','dou.png','Znak przypomina postać idącą ścieżką, spoglądając na oznakowanie [drogi].','国道 (こくどう - autostrada krajowa), 道路 (どうろ - droga)'),(93,'Mai',NULL,'Każdy','mai.png','-','毎日 (まいにち - codziennie), 毎回 (まいかい - cały czas)'),(94,'Yuu','Tomo','Przyjaciel','yuu.png','Wygląda jak dwie osoby (人), jedna z nich upada (ナ), a druga pomaga jej wstać. Przyjaciele zawsze sobie pomagają.','友達 (ともだち - przyjaciel), 親友 (しんゆう - najlepszy przyjaciel)'),(95,'Mei/Myou','Na','Imię','mei-myou.png','O świcie 夕 trudno cokolwiek dostrzec, więc trzeba wołać do ludzi po imieniu.','名前 (なまえ - imię), 名刺 (めいし - wizytówka)'),(96,'Kin/Kon','Kane','Złoto,Metal,Pieniądze','kin-kon.png','Dobry król 王 traktuje swoje królestwo jak dom (górna część znaku przypominająca dach), więc rozdziela [pieniądze] po równo (dwie równe linie po środku).','お金 (おかね - pieniądze), 金曜日 (きんようび - piątek)'),(97,'En','Marui','Koło,Yen,Okrągły','en.png','Znak przypomina okienko w banku gdzie trzyma się [yen] oraz monety są [okrągłe].','円 (えん - jen), 円い (まるい - okrągły)'),(98,'Sha','Kuruma','Samochód,Koło','sha.png','Przypomina podwozie [samochodu] na którym zamocowane są koła.','車 (くるま - pojazd), 自動車 (じどうしゃ - samochód)'),(99,'Eki',NULL,'Stacja','eki.png','Po obróceniu znaku w lewo, stwierdzić można, że znak przypomina pociąg poruszający się po torach. Pociąg wjeżdża na stacje.','発駅 (えき - stacja początkowa(kolejowa)), 駅前 (えきまえ - przed stacją)'),(100,'Ki/Kei',NULL,'Dusza,Duch,Strumień','ki-kei.png','-','天気 (てんき - pogoda), 元気 (げんき - zdrowy, żywy, energiczny)'),(101,'Koku','Kuni','Kraj','koku.png','-','国 (くに - kraj), 外国 (がいこく - zagranica)'),(102,'Sha','Yashiro','Świątynia,Firma','sha(yashiro).png','Prawa część znaku przypomina krzyż jako symbol chrześcijańskich świątyń.','神社 (じんじゃ - świątynia), 社会 (しゃかい - społeczeństwo)'),(103,'Kou',NULL,'Szkoła,Rodzaj szkoły','kou(gakkou).png','Lewa część znaku zawiera drzewo 木 jako symbol długowieczności wiedzy. [Szkoła] jest miejscem wymiany 交 wiedzy.','学校 (がっこう - szkoła), 高校 (こうこう - liceum)');
